const SITE_ORIGIN='https://douyin-studio-van-2026.hushedopal1.chatgpt.site';
const API_ROOT=location.origin===SITE_ORIGIN?'http://127.0.0.1:8765':'';
const apiUrl=path=>API_ROOT+path;
const STAGES=['download','audio','transcribe','translate','subtitles','tts','timing','render'];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let state={jobs:[],runs:[],config:{},health:{},checklist:[],stages:{}}, selected=null, reviewing=null, inputMode='link', currentView='overview', first=true;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=n=>n?new Date(n*1000).toLocaleString('vi-VN'):'—';
const dur=n=>{if(!Number.isFinite(n))return '—';let s=Math.max(0,Math.round(n));return `${Math.floor(s/3600)?Math.floor(s/3600)+'g ':''}${Math.floor(s%3600/60)}p ${s%60}g`};
const labels={running:'ĐANG CHẠY',queued:'CHỜ XỬ LÝ',blocked:'BỊ CHẶN',stopped:'ĐÃ DỪNG',completed:'HOÀN THÀNH'};
function toast(msg,error=false){let el=$('#toast');el.textContent=msg;el.className=(error?'error ':'')+'show';setTimeout(()=>el.className='',3800)}
async function api(path,method='GET',data){let res=await fetch(apiUrl(path),{method,headers:{...(method!=='GET'?{'X-Local-Action':'1','Content-Type':'application/json'}:{})},body:data===undefined?undefined:JSON.stringify(data)});let value=await res.json();if(!res.ok)throw new Error(value.error||'Có lỗi xảy ra');return value}
const job=id=>state.jobs.find(j=>j.id===id);
function go(view){currentView=view;$$('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+view));$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#current-view').textContent={overview:'Tổng quan',queue:'Hàng đợi',review:'Phụ đề & preview',history:'Lịch sử phiên',settings:'Cấu hình'}[view];if(view==='review')renderReview();if(view==='history')renderHistory()}
function status(j){return `<span class="status ${esc(j.status)}">${labels[j.status]||esc(j.status)}</span>`}
function elapsed(j){return j.started_at?(j.status==='running'?Date.now()/1000:j.finished_at||Date.now()/1000)-j.started_at:0}
function eta(j){let remaining=STAGES.filter(s=>j.stages[s]!=='done');if(!remaining.length)return '0p';let samples=state.runs.filter(r=>r.status==='completed'&&r.duration);if(!samples.length||!j.duration)return 'Chưa đủ dữ liệu';let ref=samples.find(r=>r.job_id===j.id)||samples[0],ratio=j.duration/ref.duration;let seconds=remaining.reduce((sum,s)=>sum+(ref.stages?.[s]||0)*(s==='download'?1:ratio),0);return dur(seconds)+' (ước lượng từ lịch sử)'}
function progress(j){return Math.round(STAGES.filter(s=>j.stages[s]==='done').length/8*100)}
function renderOverview(){let jobs=state.jobs,active=jobs.find(j=>j.status==='running')||jobs.find(j=>j.status==='queued')||jobs[0];$('#metric-active').textContent=jobs.filter(j=>j.status==='running').length;$('#metric-queued').textContent=jobs.filter(j=>j.status==='queued').length;$('#metric-complete').textContent=jobs.filter(j=>j.status==='completed').length;$('#metric-blocked').textContent=jobs.filter(j=>['blocked','stopped'].includes(j.status)).length;$('#queue-count').textContent=jobs.filter(j=>j.status==='queued').length;
$('#current-tag').textContent=active?`JOB ${active.id.toUpperCase()}`:'CHƯA CÓ JOB';$('#current-job').innerHTML=active?`<div class="job-head"><div><h3>${esc(active.title)}</h3><small>${esc(active.current_stage?state.stages[active.current_stage]:active.status==='completed'?'Đã hoàn thành':'Đang chờ xử lý')}</small></div>${status(active)}</div><div class="progress"><span style="width:${progress(active)}%"></span></div><div class="progress-label"><span>${progress(active)}% · ${STAGES.filter(s=>active.stages[s]==='done').length}/8 bước</span><span>Đã chạy ${dur(elapsed(active))} · Còn ${eta(active)}</span></div><div class="step-line">${STAGES.map(s=>`<span title="${esc(state.stages[s])}" class="${esc(active.stages[s])}"></span>`).join('')}</div>${active.error?`<div class="error-box">${esc(active.error)}</div>`:''}<div class="quick-actions"><button class="secondary" data-open="${active.id}">Xem các bước</button>${active.status==='running'||active.status==='queued'?`<button class="secondary" data-action="stop" data-id="${active.id}">Dừng</button>`:''}${['stopped','blocked'].includes(active.status)?`<button class="secondary" data-action="resume" data-id="${active.id}">Tiếp tục</button>`:''}</div>`:`<div class="empty-state"><b>Chưa có video trong hàng đợi</b>Thêm link Douyin hoặc file video để bắt đầu một phiên xử lý cục bộ.<div class="quick-actions" style="justify-content:center"><button class="secondary" data-go="queue">Thêm video</button></div></div>`;
let h=state.health||{},tools=h.tools||{}, gpu=h.gpu||{}, memory=h.memory||{}, custom=state.config.tts_provider==='custom',voiceReady=h.voice_ready&&(custom||tools.piper);let rows=[['ffmpeg / ffprobe',tools.ffmpeg&&tools.ffprobe?'Đã tìm thấy':'Thiếu công cụ',tools.ffmpeg&&tools.ffprobe],['Faster-Whisper',tools.faster_whisper&&h.recognition_model_ready?'Model ASR đã có':tools.faster_whisper?'Model ASR chưa có local':'Chưa cài trong Python này',tools.faster_whisper&&h.recognition_model_ready],['Ollama + model',h.ollama_ready&&h.translation_model_ready?'Model đã có':h.ollama_ready?'Chưa thấy model đã chọn':'Chưa kết nối',h.ollama_ready&&h.translation_model_ready],[custom?'Adapter TTS':'Piper + model giọng',voiceReady?'Sẵn sàng':'Chưa đủ model/công cụ',voiceReady],['GPU',gpu.available?`${esc(gpu.name)} · ${gpu.free_mib} MiB trống`:'Chưa nhận GPU',gpu.available],['RAM',memory.free_mib!==undefined?`${(memory.total_mib/1024).toFixed(1)} GB · ${(memory.free_mib/1024).toFixed(1)} GB trống`:'Chưa đo được',memory.free_mib>=state.config.min_free_ram_mib],['Cấu hình',state.config.profile_mode==='auto'?memory.total_mib>=28*1024?'Tự động · máy từ 32 GB':'Tự động · máy 16 GB':'Chỉnh tay',true]];$('#health-panel').innerHTML=`<div class="health-list">${rows.map(([n,v,ok])=>`<div class="health-item"><span>${n}</span><b class="${ok?'':'warn'}">${v}</b></div>`).join('')}</div><p class="tiny" style="margin:15px 0 0">Đã kiểm tra: ${fmtDate(h.checked_at)} · yt-dlp ${tools.yt_dlp?'có sẵn':'chưa tìm thấy'}.</p>`;
let blockers=[];if(!tools.ffmpeg||!tools.ffprobe)blockers.push('Thiếu ffmpeg hoặc ffprobe.');if(!tools.faster_whisper)blockers.push('Chưa import được Faster-Whisper.');else if(!h.recognition_model_ready)blockers.push('Model nhận diện chưa có trên máy; chọn đường dẫn model sẵn có.');if(tools.faster_whisper&&!h.cpu_fallback_model_ready)blockers.push('Model dự phòng CPU chưa có; chọn model đã có nếu muốn fallback.');if(!h.ollama_ready)blockers.push('Ollama local chưa trả lời.');else if(!h.translation_model_ready)blockers.push('Model dịch đã chọn chưa có trong Ollama.');if(!voiceReady)blockers.push(custom?'Chưa cấu hình lệnh adapter TTS.':'Chưa chọn giọng Piper .onnx và file cấu hình tương ứng.');if(memory.free_mib!==undefined&&memory.free_mib<state.config.min_free_ram_mib)blockers.push(`RAM trống chỉ ${(memory.free_mib/1024).toFixed(1)} GB, dưới ngưỡng bảo vệ ${(state.config.min_free_ram_mib/1024).toFixed(1)} GB. Đóng ứng dụng nặng trước khi xử lý.`);if(active?.error)blockers.push(active.error);let next=active?.status==='blocked'?'Đọc log, sửa lỗi hoặc câu dịch rồi chạy lại từ bước tương ứng.':!jobs.length?'Kiểm tra cấu hình giọng, model dịch và thêm video đầu tiên.':'Mở từng bước để xem log, timing và output.';
$('#evidence').innerHTML=`<div class="evidence-list"><div class="evidence-card"><b>ĐÃ KIỂM CHỨNG</b><p>${esc(gpu.available?`${gpu.name}; VRAM trống ${gpu.free_mib} MiB tại lúc kiểm tra.`:'Máy này chưa trả thông tin GPU từ nvidia-smi.')} RAM hiện còn ${memory.free_mib===undefined?'chưa đo được':(memory.free_mib/1024).toFixed(1)+' GB'}. Trạng thái công cụ được đọc trực tiếp từ engine trên máy bạn.</p></div><div class="evidence-card assumption"><b>GIẢ ĐỊNH</b><p>Giới hạn CPU và độ dài đoạn được tự chọn theo RAM của máy đang chạy, hoặc theo mục Chỉnh tay. Khả năng CUDA và tốc độ thực tế chưa được xác nhận trên máy bạn.</p></div><div class="evidence-card blocker"><b>BLOCKERS</b><p>${esc(blockers.length?blockers.join(' '):'Không phát hiện blocker từ kiểm tra nhanh. Hãy chạy một video để xác nhận toàn pipeline.')}</p></div><div class="evidence-card action"><b>NEXT ACTION</b><p>${esc(next)}</p></div></div>`;
renderChecklist();}
function renderChecklist(){if($('#checklist').contains(document.activeElement))return;$('#checklist').innerHTML=(state.checklist||[]).map((x,i)=>`<div class="check-row"><input type="checkbox" data-check="${i}" ${x.done?'checked':''} aria-label="Hoàn thành mục ${i+1}"><input type="text" data-check-text="${i}" value="${esc(x.text)}" aria-label="Mục checklist ${i+1}"><button class="remove" data-remove-check="${i}" aria-label="Xóa mục">×</button></div>`).join('')||'<p class="muted">Thêm các bước kiểm tra bạn muốn lặp lại cho mỗi video.</p>'}
async function saveChecklist(){try{state.checklist=await api('/api/checklist','POST',{items:state.checklist});renderChecklist()}catch(e){toast(e.message,true)}}
function renderQueue(){let jobs=state.jobs;if(!selected&&jobs.length)selected=jobs[0].id;$('#job-count').textContent=jobs.length+' VIDEO';$('#job-list').innerHTML=jobs.map(j=>`<div class="queue-job ${selected===j.id?'selected':''}" data-select="${j.id}"><div class="queue-job-top"><b>${esc(j.title)}</b>${status(j)}</div><small>${fmtDate(j.created_at)} · ${j.duration?dur(j.duration):'Chưa đo thời lượng'} · ${progress(j)}%</small><div class="queue-job-actions"><button class="icon-button" data-move="-1" data-id="${j.id}" title="Lên trên" aria-label="Chuyển lên">↑</button><button class="icon-button" data-move="1" data-id="${j.id}" title="Xuống dưới" aria-label="Chuyển xuống">↓</button></div></div>`).join('')||'<div class="empty-state"><b>Hàng đợi trống</b>Thêm video ở ô bên cạnh.</div>';renderDetail()}
let lastDetail='';
async function renderDetail(){let j=job(selected);if(!j){$('#detail-panel').innerHTML='<div class="empty-state">Chọn một video để xem các bước và log.</div>';return}let key=j.id+':'+j.status+':'+j.current_stage+':'+JSON.stringify(j.stages)+':'+j.error;if(key!==lastDetail){lastDetail=key;$('#detail-panel').innerHTML=`<div class="detail-top"><div><span class="eyebrow">JOB / ${esc(j.id.toUpperCase())}</span><h2>${esc(j.title)}</h2><p>${j.duration?dur(j.duration)+' · ':''}${j.sentences||0} câu thoại · ${j.chunks||0} đoạn · Đã chạy ${dur(elapsed(j))}</p></div><div class="detail-control">${j.status==='running'||j.status==='queued'?`<button class="secondary" data-action="stop" data-id="${j.id}">Dừng</button>`:''}${['stopped','blocked'].includes(j.status)?`<button class="secondary" data-action="resume" data-id="${j.id}">Tiếp tục</button>`:''}<button class="secondary" data-review="${j.id}">Xem preview</button></div></div>${j.error?`<div class="error-box">${esc(j.error)}</div>`:''}<div class="section-label">CÁC BƯỚC XỬ LÝ · BẤM CHẠY LẠI TỪ BƯỚC CẦN SỬA</div><div class="stage-grid">${STAGES.map((s,i)=>`<div class="stage-card ${esc(j.stages[s])}"><span class="stage-num">${String(i+1).padStart(2,'0')} / 08</span><b>${esc(state.stages[s])}</b><small>${j.stages[s]==='done'?dur(j.stage_times[s]||0):j.stages[s]==='waiting'?'Chưa chạy':j.stages[s]==='running'?'Đang xử lý':j.stages[s]==='blocked'?'Có lỗi':'Đã dừng'}</small><br><button data-rerun="${s}" data-id="${j.id}" ${j.status==='running'?'disabled':''}>Chạy lại từ đây</button></div>`).join('')}</div><div class="section-label">LOG XỬ LÝ</div><pre class="logbox" id="detail-log">Đang tải log…</pre><div class="section-label">GHI CHÚ / HẠN CHẾ</div><textarea class="notes" id="job-notes" placeholder="Câu bị chặn từ ngữ, thiếu timing, provider không hoàn chỉnh…">${esc(j.notes||'')}</textarea><div class="quick-actions"><button class="secondary" id="save-notes" data-id="${j.id}">Lưu ghi chú</button></div>`}try{let log=await api(`/api/jobs/${j.id}/log`);let el=$('#detail-log');if(el)el.textContent=log||'Chưa có log.'}catch(e){}}
function renderReviewSelector(){let previous=reviewing;let jobs=state.jobs;$('#review-select').innerHTML=jobs.map(j=>`<option value="${j.id}">${esc(j.title)}</option>`).join('');if(!reviewing||!job(reviewing))reviewing=jobs[0]?.id||null;if(reviewing)$('#review-select').value=reviewing;return previous!==reviewing}
async function renderReview(){let changed=renderReviewSelector();let j=job(reviewing);$('#video-preview').innerHTML=j?.output_path?`<video controls preload="metadata" src="${apiUrl('/api/jobs/'+j.id+'/output')}"><track kind="subtitles" src="${apiUrl('/api/jobs/'+j.id+'/vtt')}" srclang="vi" label="Tiếng Việt" default></video>`:'<div class="empty-state"><b>Chưa có video hoàn chỉnh</b>Output sẽ xuất hiện sau bước Ghép video.</div>';$('#downloads').innerHTML=j?`${j.output_path?`<a href="${apiUrl('/api/jobs/'+j.id+'/output')}" download="${esc(j.title)}.mp4">Tải MP4</a>`:''}${j.stages.subtitles==='done'?`<a href="${apiUrl('/api/jobs/'+j.id+'/subtitles')}" download="subtitles.srt">Tải SRT</a>`:''}${j.source_path?`<a href="${apiUrl('/api/jobs/'+j.id+'/source')}" download>Tải bản gốc</a>`:''}`:'';
if(!j){$('#transcript-list').innerHTML='<div class="empty-state">Chưa có video để xem phụ đề.</div>';return}if($('#transcript-list').dataset.job===j.id&&!changed)return;$('#transcript-list').dataset.job=j.id;
try{let rows=await api(`/api/jobs/${j.id}/segments`);$('#transcript-list').innerHTML=rows.length?`<div class="transcript-list">${rows.map((r,i)=>`<div class="segment" data-index="${i}"><span class="segment-index">${String(i+1).padStart(2,'0')}</span><div><p class="original">${esc(r.source)}</p><textarea aria-label="Bản dịch câu ${i+1}">${esc(r.target)}</textarea><div class="time-pair"><input type="number" step=".001" min="0" value="${r.start}" aria-label="Bắt đầu câu ${i+1}"><input type="number" step=".001" min="0" value="${r.end}" aria-label="Kết thúc câu ${i+1}"></div></div></div>`).join('')}</div>`:'<div class="empty-state"><b>Chưa có câu thoại</b>Nhận diện lời thoại xong sẽ hiển thị tại đây.</div>'}catch(e){toast(e.message,true)}}
function renderHistory(){let runs=state.runs, opts='<option value="">Chọn phiên</option>'+runs.map(r=>`<option value="${r.id}">${esc(job(r.job_id)?.title||r.job_id)} · ${fmtDate(r.started_at)}</option>`).join('');let a=$('#compare-a').value,b=$('#compare-b').value;$('#compare-a').innerHTML=opts;$('#compare-b').innerHTML=opts;$('#compare-a').value=a||runs[0]?.id||'';$('#compare-b').value=b||runs[1]?.id||'';$('#runs-list').innerHTML=runs.map(r=>`<div class="run-row"><b>${esc(job(r.job_id)?.title||r.job_id)}</b><span class="status ${esc(r.status)}" style="float:right">${labels[r.status]||esc(r.status)}</span><p>${fmtDate(r.started_at)} · ${dur((r.finished_at||Date.now()/1000)-r.started_at)} · ${Object.keys(r.stages||{}).length} bước chạy trong phiên</p>${r.output_path?`<a href="${apiUrl('/api/runs/'+r.id+'/output')}" download="output_${r.id}.mp4">Tải video phiên này</a> · <a href="${apiUrl('/api/runs/'+r.id+'/subtitles')}" download="subtitles_${r.id}.srt">Tải phụ đề</a>`:''}</div>`).join('')||'<p class="muted">Chưa có phiên xử lý nào.</p>';compare()}
function compare(){let a=state.runs.find(r=>r.id===$('#compare-a').value),b=state.runs.find(r=>r.id===$('#compare-b').value);if(!a||!b){$('#comparison').innerHTML='<p class="muted">Chọn hai phiên để so sánh.</p>';return}let rows=[['Kết quả',labels[a.status],labels[b.status]],['Thời gian phiên',dur((a.finished_at||Date.now()/1000)-a.started_at),dur((b.finished_at||Date.now()/1000)-b.started_at)],['Model nhận diện',a.config.recognition_model,b.config.recognition_model],['Model dịch',a.config.translation_model,b.config.translation_model],['Giọng đọc',a.config.voice_path||'—',b.config.voice_path||'—'],['Mã hóa',`${a.config.encode_preset} / CRF ${a.config.crf}`,`${b.config.encode_preset} / CRF ${b.config.crf}`],...STAGES.map(s=>[state.stages[s],a.stages?.[s]===undefined?'—':dur(a.stages[s]),b.stages?.[s]===undefined?'—':dur(b.stages[s])])];$('#comparison').innerHTML=`<table class="compare-table"><thead><tr><th>CHỈ SỐ</th><th>PHIÊN A</th><th>PHIÊN B</th></tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function updateProfileFields(){let auto=$('#config-form').elements.profile_mode.value==='auto';for(let name of ['vram_floor_mib','min_free_ram_mib','cpu_threads','parallel_cpu','chunk_seconds'])$('#config-form').elements[name].disabled=auto}function configForm(){let form=$('#config-form');Object.entries(state.config).forEach(([k,v])=>{let input=form.elements.namedItem(k);if(input)input.value=Array.isArray(v)?JSON.stringify(v):v});updateProfileFields()}$('#config-form').elements.profile_mode.addEventListener('change',updateProfileFields);
async function refresh(){try{let next=await api('/api/state');let previous=state;state=next;$('#model-list').innerHTML=(next.health.translation_models||[]).map(m=>`<option value="${esc(m.name)}">${m.size_mib} MiB trên máy</option>`).join('');$('#node-state').textContent='Đã kết nối · '+(next.jobs.filter(j=>j.status==='running').length?'đang xử lý':'sẵn sàng');$('#node-dot').classList.remove('off');$('#engine-pill').textContent='● ENGINE ONLINE';$('#engine-pill').classList.remove('offline');$('#engine-warning').hidden=true;$('#create-button').disabled=false;renderOverview();if(currentView==='queue')renderQueue();if(currentView==='history'&&previous.runs?.length!==next.runs.length)renderHistory();if(first){first=false;configForm();renderQueue();renderHistory()}}catch(e){$('#node-state').textContent='Không kết nối được';$('#node-dot').classList.add('off');$('#engine-pill').textContent='● ENGINE OFFLINE';$('#engine-pill').classList.add('offline');$('#engine-warning').hidden=false;$('#create-button').disabled=true;if(first){first=false;renderQueue();renderHistory();$('#current-job').innerHTML='<div class="empty-state"><b>Đang chờ engine trên máy bạn</b>Giải nén bản cục bộ trên Windows, chạy <code>py -3 app.py</code>. Link này là giao diện; việc dịch video diễn ra trên máy của bạn.</div>';$('#health-panel').innerHTML='<p class="muted">Chưa đọc được ffmpeg, GPU hoặc model vì engine trên máy chưa kết nối.</p>';$('#evidence').innerHTML='<div class="evidence-card blocker"><b>BLOCKER</b><p>Máy chủ Site không có model hoặc quyền truy cập máy cá nhân. Khởi chạy engine local để bắt đầu.</p></div>'}}}
async function action(id,act,data={}){try{await api(`/api/jobs/${id}/${act}`,'POST',data);toast(act==='stop'?'Đang dừng sau thao tác hiện tại':act==='resume'?'Đã đưa lại vào hàng đợi':'Đã cập nhật');await refresh();return true}catch(e){toast(e.message,true);return false}}
document.addEventListener('click',async e=>{let target=e.target.closest('button,[data-select]');if(!target)return;let d=target.dataset;if(d.view)go(d.view);if(d.go)go(d.go);if(d.select){selected=d.select;lastDetail='';renderQueue()}if(d.open){selected=d.open;lastDetail='';go('queue');renderQueue()}if(d.review){reviewing=d.review;$('#transcript-list').dataset.job='';go('review')}if(d.action)action(d.id,d.action);if(d.rerun){if(confirm(`Chạy lại từ bước “${state.stages[d.rerun]}”? Các bước sau đó sẽ được thực hiện lại.`))action(d.id,'rerun',{stage:d.rerun})}if(d.move){e.stopPropagation();action(d.id,'move',{delta:Number(d.move)})}if(d.input){inputMode=d.input;$$('[data-input]').forEach(x=>x.classList.toggle('selected',x.dataset.input===inputMode));$('#link-input').hidden=inputMode!=='link';$('#file-input').hidden=inputMode!=='file'}if(d.removeCheck!==undefined){state.checklist.splice(+d.removeCheck,1);saveChecklist()}if(target.id==='add-check'){state.checklist.push({text:'Kiểm tra video và phụ đề',done:false});saveChecklist()}if(target.id==='refresh-health'||target.id==='retry-engine')refresh();if(target.id==='save-notes')action(d.id,'notes',{notes:$('#job-notes').value})});
document.addEventListener('change',e=>{if(e.target.dataset.check!==undefined){state.checklist[+e.target.dataset.check].done=e.target.checked;saveChecklist()}if(e.target.dataset.checkText!==undefined){state.checklist[+e.target.dataset.checkText].text=e.target.value;saveChecklist()}});
$('#review-select').addEventListener('change',e=>{reviewing=e.target.value;$('#transcript-list').dataset.job='';renderReview()});$('#compare-a').addEventListener('change',compare);$('#compare-b').addEventListener('change',compare);
$('#save-segments').addEventListener('click',async()=>{let j=job(reviewing);if(!j)return;let rows=$$('.segment').map(x=>({target:x.querySelector('textarea').value,start:Number(x.querySelectorAll('input')[0].value),end:Number(x.querySelectorAll('input')[1].value)}));if(await action(j.id,'segments',{rows})){ $('#transcript-list').dataset.job='';await renderReview()}});
$('#config-form').addEventListener('submit',async e=>{e.preventDefault();let cfg=Object.fromEntries(new FormData(e.target));try{let result=await api('/api/config','POST',cfg);state.config=result.config;state.health=result.health;configForm();$('#settings-result').textContent='Đã lưu. Job mới sẽ dùng cấu hình này.';toast('Đã lưu cấu hình');renderOverview()}catch(err){toast(err.message,true)}});
$('#create-form').addEventListener('submit',async e=>{e.preventDefault();let button=$('#create-button');button.disabled=true;try{let payload={title:$('#job-title').value.trim()};if(inputMode==='link'){payload.url=$('#video-url').value.trim();if(!payload.url)throw Error('Hãy nhập liên kết video')}else{let file=$('#video-file').files[0];if(!file)throw Error('Hãy chọn file video');let start=await api('/api/upload/start','POST',{name:file.name,size:file.size});let chunkSize=4*1024*1024;$('#upload-progress').hidden=false;for(let off=0;off<file.size;off+=chunkSize){let blob=file.slice(off,off+chunkSize);let res=await fetch(apiUrl('/api/upload/'+start.token),{method:'POST',headers:{'X-Local-Action':'1','X-Offset':String(off)},body:blob});let result=await res.json();if(!res.ok)throw Error(result.error);$('#upload-progress').textContent=`Đang sao chép: ${Math.round(result.received/file.size*100)}%`}payload.upload=start.token}let j=await api('/api/jobs','POST',payload);selected=j.id;$('#job-title').value='';$('#video-url').value='';$('#video-file').value='';$('#upload-progress').hidden=true;lastDetail='';toast('Đã thêm vào hàng đợi');await refresh()}catch(err){toast(err.message,true)}finally{button.disabled=false}});
$('#clock').textContent=new Date().toLocaleString('vi-VN',{dateStyle:'medium',timeStyle:'short'});refresh();setInterval(refresh,3500);
